package be.winnetrie.mod.simpleserverutilities.network;
import be.winnetrie.mod.simpleserverutilities.SimpleServerUtilities;import net.minecraft.network.RegistryFriendlyByteBuf;import net.minecraft.network.codec.StreamCodec;import net.minecraft.network.protocol.common.custom.CustomPacketPayload;import net.minecraft.resources.ResourceLocation;
public record QuestEditorResultPayload(boolean successful,String message,String questId,long requestId) implements CustomPacketPayload{
 public static final Type<QuestEditorResultPayload> TYPE=new Type<>(ResourceLocation.fromNamespaceAndPath(SimpleServerUtilities.MODID,"quest_editor_result"));
 public static final StreamCodec<RegistryFriendlyByteBuf,QuestEditorResultPayload> STREAM_CODEC=StreamCodec.of(QuestEditorResultPayload::encode,QuestEditorResultPayload::decode);
 public QuestEditorResultPayload{message=PayloadBounds.string(message,512);questId=PayloadBounds.string(questId,64);requestId=Math.max(0L,requestId);}private static void encode(RegistryFriendlyByteBuf b,QuestEditorResultPayload p){b.writeBoolean(p.successful);b.writeUtf(p.message,512);b.writeUtf(p.questId,64);b.writeVarLong(p.requestId);}private static QuestEditorResultPayload decode(RegistryFriendlyByteBuf b){return new QuestEditorResultPayload(b.readBoolean(),b.readUtf(512),b.readUtf(64),b.readVarLong());}@Override public Type<? extends CustomPacketPayload> type(){return TYPE;}}
